const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const projects={
 canopy:{name:'The Canopy Residences',location:'Balewadi, Pune · Signature residences',image:'assets/residences.jpg',description:'An imagined collection of light-filled residences with generous balconies, calm interiors and landscaped spaces. Designed around the simple pleasure of coming home.',type:'3 & 4 bedrooms',area:'1,650–2,400 sq. ft.*',features:['Private balconies and generous living areas','Landscaped gardens and spaces to meet','A considered clubhouse and fitness space','Convenient access to the city']},
 grove:{name:'The Grove Villas',location:'Baner, Pune · Private villa collection',image:'assets/hero.jpg',description:'A private retreat with room to grow. This concept brings together open living, intimate courtyards and generous terraces for a life in balance.',type:'4 & 5 bedrooms',area:'3,200–4,500 sq. ft.*',features:['Private gardens and outdoor living','Double-height living spaces','Thoughtful indoor–outdoor connections','Flexible spaces for work and leisure']},
 one:{name:'Aurelia One',location:'Kharadi, Pune · Contemporary workspaces',image:'assets/commercial.jpg',description:'A new perspective on the working day. An illustrative address for ambitious businesses, pairing contemporary architecture with a thoughtful workplace experience.',type:'Offices & retail',area:'800–3,000 sq. ft.*',features:['Flexible boutique office configurations','A welcoming arrival experience','Dedicated collaboration areas','Designed for connectivity and convenience']}
};
function openDialog(dialog){if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');}
function closeDialog(dialog){dialog.close();if(!$$('dialog[open]').length)document.body.classList.remove('modal-open');}
$$('dialog').forEach(dialog=>{$('.dialog-close',dialog).addEventListener('click',()=>closeDialog(dialog));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(dialog);}});dialog.addEventListener('close',()=>{if(!$$('dialog[open]').length)document.body.classList.remove('modal-open');});});
const menu=$('.menu-toggle');menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(expanded));menu.setAttribute('aria-label',expanded?'Close navigation':'Open navigation');$('.nav').classList.toggle('open',expanded);});
$$('.nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');$('.nav').classList.remove('open');}));
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});let count=0;$$('.project-card').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;if(!card.hidden)count++;});$('.project-count').textContent=String(count).padStart(2,'0')+(count===1?' CURATED ADDRESS':' CURATED ADDRESSES');}));
let selectedProject='';
$$('[data-project]').forEach(button=>button.addEventListener('click',()=>{selectedProject=button.dataset.project;const p=projects[selectedProject];$('#project-title').textContent=p.name;$('#detail-location').textContent=p.location;$('#detail-image').src=p.image;$('#detail-image').alt=p.name+' — illustrative architecture photograph';$('#detail-description').textContent=p.description;$('#detail-facts').replaceChildren(...[['COLLECTION',p.type],['SAMPLE SIZE',p.area]].map(([label,value])=>{const el=document.createElement('div');const small=document.createElement('small');small.textContent=label;const span=document.createElement('span');span.textContent=value;el.append(small,span);return el;}));$('#detail-features').replaceChildren(...p.features.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));openDialog($('#project-dialog'));}));
function enquire(interest){if(interest)$('#visit-form select').value=interest;$('.form-status',$('#visit-form')).textContent='';openDialog($('#visit-dialog'));}
$$('[data-enquire]').forEach(b=>b.addEventListener('click',()=>enquire()));$('#detail-enquire').addEventListener('click',()=>{closeDialog($('#project-dialog'));enquire(projects[selectedProject].name);});
const now=new Date();const localDate=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');$('#visit-form input[type=date]').min=localDate;
$('#visit-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const date=new Date(data.get('date')+'T12:00:00');$('.form-status',e.currentTarget).textContent=`Your request preview is ready, ${data.get('name').trim()}: ${data.get('interest')} on ${date.toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}. This is a demonstration; no visit has been booked and no details have been sent.`;});
$('#contact-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);$('.form-status',e.currentTarget).textContent=`Thank you, ${data.get('name').trim()}. Your enquiry preview for ${data.get('interest')} is ready. In the live website, the team would reply to ${data.get('email')}. No details have been sent or stored in this demo.`;});
const heroSlides=[{image:'assets/hero.jpg',caption:'THE GROVE COLLECTION',location:'Private villas · Baner, Pune',alt:'Contemporary private villa with greenery and a pool'},{image:'assets/residences.jpg',caption:'THE CANOPY RESIDENCES',location:'Signature residences · Balewadi, Pune',alt:'Modern residences framed by mature trees'},{image:'assets/living.jpg',caption:'THE ART OF LIVING WELL',location:'Thoughtful spaces · The Aurelia collection',alt:'Beautifully detailed contemporary interiors with natural light'}];let heroIndex=0;
function showHero(delta){heroIndex=(heroIndex+delta+heroSlides.length)%heroSlides.length;const s=heroSlides[heroIndex];$('#hero-image').src=s.image;$('#hero-image').alt=s.alt;$('#hero-caption').textContent=s.caption;$('#hero-location').textContent=s.location;$('#slide-index').textContent=String(heroIndex+1).padStart(2,'0');}
$('#hero-prev').addEventListener('click',()=>showHero(-1));$('#hero-next').addEventListener('click',()=>showHero(1));
const gallery=[{image:'assets/pool.jpg',title:'Space to unwind',alt:'A quiet landscaped pool and contemporary residence'},{image:'assets/living.jpg',title:'Room to feel at home',alt:'Open contemporary living spaces and refined natural materials'},{image:'assets/hero.jpg',title:'Closer to the outdoors',alt:'Architect-designed private villa with indoor and outdoor living'}];let galleryIndex=0;
function showGallery(delta=0){galleryIndex=(galleryIndex+delta+gallery.length)%gallery.length;const s=gallery[galleryIndex];$('#gallery-image').src=s.image;$('#gallery-image').alt=s.alt;$('#gallery-title').textContent=s.title;$('#gallery-count').textContent=`${galleryIndex+1} / ${gallery.length}`;}
$$('[data-gallery]').forEach(b=>b.addEventListener('click',()=>{showGallery();openDialog($('#gallery-dialog'));}));$('#gallery-prev').addEventListener('click',()=>showGallery(-1));$('#gallery-next').addEventListener('click',()=>showGallery(1));$('#privacy-button').addEventListener('click',()=>openDialog($('#privacy-dialog')));
